import { readFileSync, writeFileSync } from "node:fs";

const SOURCES = [
  {
    constant: "DICEWARE_CA",
    language: "Català",
    source: "assets/wordlists/diceware_ca.txt",
  },
  {
    constant: "DICEWARE_ES",
    language: "Castellà",
    source: "assets/wordlists/diceware_es.txt",
  },
];
const TARGET = "src-web/wordlist-diceware.js";
const MIN_WORD_LENGTH = 3;
const MAX_WORD_LENGTH = 16;
const MIN_WORDS = 4000;
const WORD_RE = new RegExp(
  `^\\p{L}{${MIN_WORD_LENGTH},${MAX_WORD_LENGTH}}$`,
  "u",
);

const HEADER = `// SherLock username wordlists (Diceware)
// Generated by tools/build_diceware_wordlists.mjs from assets/wordlists/diceware_ca.txt and diceware_es.txt.
// Source: webpassgen (https://github.com/atoponce/webpassgen), lists/dicewareCA.js and lists/dicewareES.js.
// Upstream Diceware wordlists: https://www.diceware.com/
// License: webpassgen is AGPL-3.0; the wordlist data keeps its upstream terms. See assets/wordlists/README.md.
// Filtered for usernames: lowercase entries, letters only, ${MIN_WORD_LENGTH}-${MAX_WORD_LENGTH} characters, duplicate-free.
// Do NOT edit this file by hand; regenerate with: node tools/build_diceware_wordlists.mjs
`;

function readWordlist({ language, source }) {
  const lines = readFileSync(source, "utf8").split("\n");
  const words = [];
  const seen = new Set();
  let skipped = 0;

  for (const line of lines) {
    const raw = line.trim();
    if (!raw) continue;
    // Uppercase entries in the Spanish list are mostly proper nouns and
    // acronyms (Madrid, PSOE, BMW); they make poor usernames.
    if (raw !== raw.toLowerCase()) {
      skipped += 1;
      continue;
    }
    const word = raw.normalize("NFC");
    if (!WORD_RE.test(word)) {
      skipped += 1;
      continue;
    }
    if (seen.has(word)) continue;
    seen.add(word);
    words.push(word);
  }

  if (words.length < MIN_WORDS) {
    throw new Error(
      `${language}: només ${words.length} paraules vàlides a ${source} (mínim ${MIN_WORDS})`,
    );
  }

  console.log(
    `${language}: ${words.length} paraules vàlides, ${skipped} descartades (${source}).`,
  );
  return Object.freeze(words);
}

function main() {
  const lists = SOURCES.map((source) => ({
    ...source,
    words: readWordlist(source),
  }));

  const arrays = lists
    .map(
      ({ constant, words }) =>
        `export const ${constant} = Object.freeze([\n${words
          .map((word) => `  ${JSON.stringify(word)},`)
          .join("\n")}\n]);\n`,
    )
    .join("\n");

  const registry = `export const DICEWARE_USERNAME_WORDLISTS = Object.freeze({\n${lists
    .map(({ language, constant }) => `  ${language}: ${constant},`)
    .join("\n")}\n});\n`;

  writeFileSync(TARGET, `${HEADER}\n${arrays}\n${registry}`, "utf8");
  console.log(`Generat ${TARGET}.`);
}

main();
